window.DocsIndex={el:"#docs",name:"DocsIndex",data:function(){return _.merge({categories:!1,posts:!1,config:{filter:this.$session.get("documents.filter",{order:"priority asc",limit:50})},pages:0,count:"",selected:[],modalDraft:{id:null,title:null,slug:null,status:3,roles:[]}},window.$data)},created:function(){this.resource=this.$resource("admin/docs/api{/id}")},ready:function(){this.$watch("config.page",this.load,{immediate:!0});var t=this,e=this.$el.querySelector(".docs-category");e&&SK.sortable(e).element.on("change.sk.sortable",function(e,i,s,n){"moved"!==n&&"added"!==n||t.reorder(i)});var i=this.$el.querySelector(".docs-post-list");i&&SK.sortable(i).element.on("change.sk.sortable",function(e,i,s,n){"moved"!==n&&"added"!==n||t.reorderPosts(i)})},watch:{"config.filter":{handler:function(t){this.config.page?this.config.page=0:this.load(),this.$session.set("documents.filter",t)},deep:!0}},computed:{statusOptions:function(){var t=_.map(this.statuses,function(t,e){return{text:t,value:e}});return[{label:this.$trans("Filter by"),options:t}]},categoryOptions:function(){var t=_.map(this.categories,function(t){return{text:t.title,value:t.id}});return[{label:this.$trans("Filter by"),options:t}]},draftCategory:function(){return{id:null,title:null,slug:null,status:3,roles:[]}}},methods:{load:function(){this.resource.query({filter:this.config.filter,page:this.config.page}).then(function(t){var e=t.data;this.$set("posts",e.posts),this.$set("pages",e.pages),this.$set("count",e.count),this.$set("selected",[])},function(t){this.$notify(t.data,"danger")})},reorder:function(t){var e=this;t.element.children().each(function(t){var i=parseInt(this.getAttribute("data-id"),10),s=_.find(e.categories,{id:i});s&&s.priority!==t&&(s.priority=t,e.saveCategory(s))})},saveCategory:function(t,e){this.$http.post("admin/docs/api/savecategory",{category:t,id:t.id}).then(function(){t.id&&!e||location.reload()},function(t){this.$notify(t.data,"danger")})},reorderPosts:function(t){var e=this;t.element.children().each(function(t){var i=parseInt(this.getAttribute("data-id"),10),s=_.find(e.posts,{id:i});s&&s.priority!==t&&(s.priority=t,e.savePost(s))})},savePost:function(t){this.$http.post("admin/docs/api/save",{data:t,id:t.id}).then(function(){},function(t){this.$notify(t.data,"danger")})},deleteCategory:function(t){this.$http.get("admin/docs/api/bulkcategorydelete",{params:{id:t}}).then(function(){location.reload()},function(t){this.$notify(t.data,"danger")})},openModal:function(t){this.modalDraft=t,this.$refs.modal.open()},close:function(){this.$refs.modal.close()},onClose:function(){this.modalDraft=this.draftCategory},status:function(t){var e=this.getSelected();e.forEach(function(e){e.status=t}),this.resource.save({id:"bulk"},{posts:e}).then(function(){this.load(),this.$notify("Posts saved.")})},remove:function(){this.resource.delete({id:"bulk"},{ids:this.selected}).then(function(){this.load(),this.$notify("Posts deleted.")})},getSelected:function(){return this.posts.filter(function(t){return-1!==this.selected.indexOf(t.id)},this)},getStatusText:function(t){return this.statuses[t.status]}}},Vue.ready(window.DocsIndex);